import math
from functools import lru_cache

def count_binary_seq(n):
    @lru_cache(None)
    def helper(pos, diff):
        # Base case: If we've processed all 2n bits, the sequence is valid if diff == 0
        if pos == 2 * n:
            return 1 if diff == 0 else 0

        # If we're still in the first n bits, adjust diff accordingly
        if pos < n:
            return helper(pos + 1, diff + 1) + helper(pos + 1, diff - 1)
        # If we're in the last n bits, adjust diff in the reverse direction
        else:
            return helper(pos + 1, diff - 1) + helper(pos + 1, diff + 1)

    # Start recursion from position 0 with a difference of 0
    return helper(0, 0)

# Tests
