def find_kth(arr1, arr2, k):
    def kth_element(a, b, k):
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]
        if k == 1:
            return min(a[0], b[0])

        a_mid_index = min(len(a), k // 2) - 1
        b_mid_index = min(len(b), k // 2) - 1

        a_mid = a[a_mid_index]
        b_mid = b[b_mid_index]

        if a_mid <= b_mid:
            return kth_element(a[a_mid_index + 1:], b, k - (a_mid_index + 1))
        else:
            return kth_element(a, b[b_mid_index + 1:], k - (b_mid_index + 1))

    return kth_element(arr1, arr2, k)

# Example usage:
# assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
