def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into one. If there are duplicate keys,
    the value from the dictionary that appears later in the merge will overwrite the earlier ones.
    To ensure consistent ordering of keys, the final dictionary is sorted by the keys.
    """
    merged_dict = {}
    for d in (dict1, dict2, dict3):
        merged_dict.update(d)
    return dict(sorted(merged_dict.items()))

# Test the function
